// Bộ ảnh mèo Bug anime: 1 ảnh lưới 3x3 gồm 9 biểu cảm (vẽ bằng AI theo ảnh Bug thật,
// đã tách nền xanh, nén WebP rồi nhúng base64 vào file chữ này để đẩy GitHub trọn vẹn).
// Thứ tự ô: 0 thường · 1 vui · 2 lấp lánh · 3 ngủ · 4 hài lòng · 5 kêu · 6 tập trung · 7 giận · 8 yêu
export const CAT_SHEET = 'data:image/webp;base64,';

/** Hành động của game -> ô biểu cảm trong lưới */
export const CELL_BY_ACTION: Record<string, number> = {
  idle: 0,
  chay: 1,
  lan: 1,
  nhay: 2,
  ngu: 3,
  an: 4,
  keu: 5,
  duoi: 6,
  gian: 7,
  thuong: 8,
};

/** background-position để hiện đúng 1 ô trong lưới 3x3 (background-size 300% 300%) */
export const cellPos = (idx: number) => `${(idx % 3) * 50}% ${Math.floor(idx / 3) * 50}%`;
